16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName",
23	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
24	    @Mapping(target = "initials", expression = "java(initials(owner))")
25	    @Mapping(target = "membershipTier", expression = "java(membershipTier(owner))")
26	    @Mapping(target = "locality", expression = "java(locality(owner))")
27	    // Not derivable from a single owner; the responder sets it from the daily registration count.
28	    @Mapping(target = "bulkSignupWarning", ignore = true)
29	    OwnerDto toOwnerDto(Owner owner);
30	
31	    /**
32	     * The owner's locality: the canonical region derived from its city via the pinned
33	     * city-to-region table, or "UNKNOWN" for any city not in the table.
34	     */
35	    default String locality(Owner owner) {
36	        return CityRegion.localityOf(owner.getCity());
37	    }
38	
39	    /**
40	     * The owner's membership tier: GOLD when their household had 3 or more members after
41	     * they were created; otherwise SILVER when they have no namesakes and a stored email
42	     * address, and BRONZE in every other case.
43	     */
44	    default OwnerDto.MembershipTierEnum membershipTier(Owner owner) {
45	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
46	            return OwnerDto.MembershipTierEnum.GOLD;
47	        }
48	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
49	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
50	        return noNamesakes && hasEmail ? OwnerDto.MembershipTierEnum.SILVER
51	            : OwnerDto.MembershipTierEnum.BRONZE;
52	    }
53	
54	    /**
55	     * The upper-cased first letters of firstName and lastName, dot-separated with a
56	     * trailing dot (e.g. "J.S.").
57	     */
58	    default String initials(Owner owner) {
59	        return firstInitial(owner.getFirstName()) + firstInitial(owner.getLastName());
60	    }
61	
62	    private static String firstInitial(String name) {
63	        return Character.toUpperCase(name.charAt(0)) + ".";
64	    }
65	
66	    Owner toOwner(OwnerDto ownerDto);
67	
68	    @Mapping(target = "id", ignore = true)
69	    @Mapping(target = "pets", ignore = true)
70	    Owner toOwner(OwnerFieldsDto ownerDto);
71	
72	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
73	
74	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
75	
76	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
77	        OwnerPageDto ownerPageDto = new OwnerPageDto();
78	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
79	        ownerPageDto.setPage(ownerPage.getNumber());
80	        ownerPageDto.setSize(ownerPage.getSize());
81	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
82	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
83	        return ownerPageDto;
84	    }
